import{o,c as a,a2 as r,k as t,e as s,F as c,B as d}from"./chunks/framework.BaXgE4DV.js";const l=JSON.parse(`[{"id":"GRATO-12","html":"<h3 id=\\"ladder-active-days-circle-posts\\" tabindex=\\"-1\\">새 배지 조건: 기록한 날, Circle에 나눈 감사 <a class=\\"header-anchor\\" href=\\"#ladder-active-days-circle-posts\\" aria-label=\\"Permalink to &quot;새 배지 조건: 기록한 날, Circle에 나눈 감사 {#ladder-active-days-circle-posts}&quot;\\">&ZeroWidthSpace;</a></h3>\\n<ul>\\n<li>배지 조건 <strong>기록한 날</strong>(<code>active_days</code>, 누적)과 <strong>Circle에 나눈 감사</strong>(<code>circle_posts</code>, 숨긴 글 제외)를 서버가 셉니다. 배지 상세·관리자 화면에 조건 이름이 보입니다.</li>\\n<li>보상 사다리 배지(기록한 날 3–100일, Circle에 나눈 감사 1–100개, 받은 공감 3–100개)는 설정 스크립트 <code>setupBadgeLadder</code>로 <strong>꺼진 채</strong> 만들고 길마다 켭니다. → <a href=\\"/grato-docs/features/stats-badges#ladder\\">보상 사다리 배지</a></li>\\n<li>배포: 규칙 변경 없음. 인덱스(<code>gratitudes</code> <code>userId</code>+<code>groupId</code>)·함수 → 인덱스 확인 → 스크립트 → 웹. → <a href=\\"/grato-docs/operations/deploy#release-badge-ladder\\">배포</a></li>\\n</ul>\\n"},{"id":"GRATO-14","html":"<h3 id=\\"ladder-reactions-comments-given\\" tabindex=\\"-1\\">새 배지 조건: 공감 보내기, 댓글 남기기 <a class=\\"header-anchor\\" href=\\"#ladder-reactions-comments-given\\" aria-label=\\"Permalink to &quot;새 배지 조건: 공감 보내기, 댓글 남기기 {#ladder-reactions-comments-given}&quot;\\">&ZeroWidthSpace;</a></h3>\\n<ul>\\n<li>친구 글에 처음 공감하거나 댓글을 달면 서버가 글마다 한 번 세고(떼거나 지우고 다시 해도 한 번, 내 글·숨긴 댓글 제외) 그 자리에서 배지를 평가합니다 — 축하 카드가 바로 뜹니다.</li>\\n<li>사다리 배지: 공감 보내기 1·10·30·100, 댓글 남기기 1·10·30(꺼진 채 만들어 <code>setupBadgeLadder --enable</code>). → <a href=\\"/grato-docs/features/stats-badges#conditions\\">조건 종류</a></li>\\n<li>배포: 함수 → <code>backfillGivenActivity</code>(지난 공감·댓글, 1회) → 배지 만들기. 규칙 변경 없음. → <a href=\\"/grato-docs/operations/deploy#release-badge-ladder\\">배포</a></li>\\n</ul>\\n"},{"id":"GRATO-15","html":"<h3 id=\\"ladder-invites-joined\\" tabindex=\\"-1\\">새 배지 조건: 초대 — 초대한 사람을 서버가 기록 <a class=\\"header-anchor\\" href=\\"#ladder-invites-joined\\" aria-label=\\"Permalink to &quot;새 배지 조건: 초대 — 초대한 사람을 서버가 기록 {#ladder-invites-joined}&quot;\\">&ZeroWidthSpace;</a></h3>\\n<ul>\\n<li>초대하기·복사로 보내는 링크 끝에 보낸 사람의 짧은 참조(<code>?from=</code>, uid 아님)가 붙고, 그 링크로 누가 Circle에 <strong>처음</strong> 들어오면 서버가 보낸 사람을 기록합니다(다시 들어옴·자기 링크·나간 사람 제외, 한 사람은 1명). 보낸 사람은 그 자리에서 배지 평가.</li>\\n<li>사다리 배지: 초대 1 · 마음의 다리 / 3 · 온기를 잇는 이 / 10 · 모임의 등불. → <a href=\\"/grato-docs/features/circles#invite-credits\\">초대 배지</a></li>\\n<li>배포: 새 callable <code>getInviterRef</code>, <code>joinCircle</code>·<code>createCircle</code>·<code>deleteAccount</code> 변경 → 함수 먼저, Hosting 뒤. 앱은 1.0.1 (7)부터 링크에 참조. → <a href=\\"/grato-docs/operations/deploy#release-badge-ladder\\">배포</a></li>\\n</ul>\\n"},{"id":"GRATO-16","html":"<h3 id=\\"reward-reaction-per-badge\\" tabindex=\\"-1\\">보상 공감 이모지를 배지마다 고르기 <a class=\\"header-anchor\\" href=\\"#reward-reaction-per-badge\\" aria-label=\\"Permalink to &quot;보상 공감 이모지를 배지마다 고르기 {#reward-reaction-per-badge}&quot;\\">&ZeroWidthSpace;</a></h3>\\n<ul>\\n<li>관리자 › 배지에서 배지마다 보상 공감 이모지(없음·🌸·🍀·🌈)를 고릅니다(<code>badges/{id}.reaction</code>). 고르지 않은 배지는 지금처럼(7일 연속 🌸, 감사 50개 🍀, 30일 연속 🌈). 한 번 받은 이모지는 옮기거나 빼도 남습니다.</li>\\n<li>공감 고르기 창의 &quot;'…' 배지를 받으면 쓸 수 있어요&quot;가 배지 목록에서 지금 주는 배지 이름을 찾습니다. → <a href=\\"/grato-docs/features/stats-badges#reward-reactions\\">보상 공감</a></li>\\n<li>배포: 규칙(<code>badges.reaction</code> 검사) → 함수 → Hosting. 이모지 목록 세 곳(앱·함수 JSON·규칙)은 그대로. → <a href=\\"/grato-docs/operations/deploy#release-badge-ladder\\">배포</a></li>\\n</ul>\\n"},{"id":"GRATO-27","html":"<h3 id=\\"question-recommends\\" tabindex=\\"-1\\">질문 추천과 추천 많은 질문 <a class=\\"header-anchor\\" href=\\"#question-recommends\\" aria-label=\\"Permalink to &quot;질문 추천과 추천 많은 질문 {#question-recommends}&quot;\\">&ZeroWidthSpace;</a></h3>\\n<ul>\\n<li>질문으로 쓰기의 첫 질문에 <strong>[이 질문 추천]</strong> 버튼이 생겼습니다. 질문마다 한 번, 다시 누르면 취소, 내가 제안한 질문은 추천할 수 없습니다. → <a href=\\"/grato-docs/features/questions#recommends\\">질문 추천</a></li>\\n<li><strong>&quot;추천 많은 질문&quot;</strong>: 추천받은 질문을 많은 순으로 10개까지 모아 보고, 골라서 바로 쓸 수 있습니다. 숫자 없이 순서로만 보입니다.</li>\\n<li>제안자는 마이페이지 &quot;내가 제안한 질문&quot;에서 질문마다 받은 추천 수를 봅니다. 새 배지: 추천받은 질문 10(호칭 &quot;마음 여는 질문&quot;), 50(&quot;모두의 질문&quot;).</li>\\n<li>배포: 규칙·인덱스(<code>recommends.userId</code> 컬렉션 그룹) → 함수(<code>onQuestionRecommendWritten</code> 새 함수, <code>deleteAccount</code>) → 인덱스 &quot;사용 설정됨&quot; 확인 → Hosting. → <a href=\\"/grato-docs/architecture/data-model#question-recommends\\">데이터 모델</a></li>\\n</ul>\\n"},{"id":"GRATO-28","html":"<h3 id=\\"question-answers\\" tabindex=\\"-1\\">내 질문으로 쓰인 감사 <a class=\\"header-anchor\\" href=\\"#question-answers\\" aria-label=\\"Permalink to &quot;내 질문으로 쓰인 감사 {#question-answers}&quot;\\">&ZeroWidthSpace;</a></h3>\\n<ul>\\n<li>&quot;질문으로 쓰기&quot;로 저장한 글에 어떤 질문으로 썼는지(질문 ID)가 남습니다. 글 내용은 그대로 내 글이고, 질문 ID는 나중에 바꿀 수 없습니다.</li>\\n<li>마이페이지 &quot;내가 제안한 질문&quot;에 내 질문으로 다른 사람들이 쓴 감사 수가 보입니다(합계와 질문마다). 나만 보기 글도 숫자로만 들어가고, 어떤 글인지·누가 썼는지는 보이지 않습니다. → <a href=\\"/grato-docs/features/questions#answers\\">내 질문으로 쓰인 감사</a></li>\\n<li>새 배지: 질문으로 쓰인 감사 10(호칭 &quot;감사의 씨앗&quot;), 50(&quot;고마움의 불씨&quot;). → <a href=\\"/grato-docs/features/stats-badges#question-badges\\">질문 배지</a></li>\\n<li>배포: 규칙(<code>questionId</code>, <code>questionStats</code>) + 함수(<code>onGratitudeCreated</code>, <code>onGratitudeDeleted</code>, <code>deleteAccount</code>) → Hosting. 새 인덱스 없음. → <a href=\\"/grato-docs/architecture/data-model#question-stats\\">데이터 모델</a></li>\\n</ul>\\n"},{"id":"GRATO-29","html":"<h3 id=\\"question-honors\\" tabindex=\\"-1\\">질문 배지: 오늘의 주제가 된 질문, 이달의 질문 <a class=\\"header-anchor\\" href=\\"#question-honors\\" aria-label=\\"Permalink to &quot;질문 배지: 오늘의 주제가 된 질문, 이달의 질문 {#question-honors}&quot;\\">&ZeroWidthSpace;</a></h3>\\n<ul>\\n<li>내가 제안한 질문이 모두의 감사방 오늘의 주제로 올라가면 배지(<code>topics_selected</code>) — 매일 07:02 KST에 평가해 그때 축하합니다.</li>\\n<li>&quot;이달의 질문&quot;의 제안자에게 그 달 배지와 호칭(&quot;2026 11월의 질문&quot;), 선택으로 보상 공감·테마(스크립트 <code>awardQuestionOfMonth</code>). 상위 질문은 그 달에 그 질문으로 쓰인 감사 수, 같으면 추천 수로 자동으로 고르고 운영자가 직접 고를 수도 있어요. 이 호칭은 모두의 감사방의 별명 옆에는 보이지 않아요(별명 뒤의 사람을 알 수 있어서). → <a href=\\"/grato-docs/features/questions#question-honors\\">질문 배지</a></li>\\n<li>배포: 인덱스(<code>dailyTopics</code> <code>questionId</code>+<code>publishAt</code>)·새 예약 함수 <code>creditDailyTopic</code> → 배지 만들기. → <a href=\\"/grato-docs/operations/deploy#release-badge-ladder\\">배포</a></li>\\n</ul>\\n"},{"id":"GRATO-32","html":"<h3 id=\\"activity-metrics\\" tabindex=\\"-1\\">연 사람·쓴 사람 하루 기록과 매일 밤 지표 집계 <a class=\\"header-anchor\\" href=\\"#activity-metrics\\" aria-label=\\"Permalink to &quot;연 사람·쓴 사람 하루 기록과 매일 밤 지표 집계 {#activity-metrics}&quot;\\">&ZeroWidthSpace;</a></h3>\\n<ul>\\n<li>앱·웹을 연 날(KST 하루 한 번, 첫 화면이 뜬 뒤)과 감사를 쓴 날을 사람마다 서버 전용 문서 <code>userActivity</code>에 남김. 화면에 보이는 변화 없음 → <a href=\\"/grato-docs/operations/metrics#activity\\">운영 지표: 매일 집계</a></li>\\n<li>매일 00:10 KST에 어제의 DAU·WAU·MAU(연 사람·쓴 사람), L7·L28, L7 습관층, 가입일별 코호트(classic·rolling D1·D7·D30·6개월째)를 <code>dailyMetrics</code>·<code>cohorts</code>에 저장 → <a href=\\"/grato-docs/decisions#adr-45\\">ADR-45</a></li>\\n<li>계정을 삭제하면 활동 문서도 지움. 관리자 지표의 초대 이벤트는 최근 30일만 읽음</li>\\n<li>함수 먼저, 그다음 <code>backfillUserActivity</code>, 그다음 Hosting → <a href=\\"/grato-docs/operations/deploy#release-activity-metrics\\">배포</a></li>\\n</ul>\\n"},{"id":"GRATO-33","html":"<h3 id=\\"habit-dashboard\\" tabindex=\\"-1\\">관리자 습관 지표: L7 습관층·DAU/WAU/MAU·classic 리텐션 <a class=\\"header-anchor\\" href=\\"#habit-dashboard\\" aria-label=\\"Permalink to &quot;관리자 습관 지표: L7 습관층·DAU/WAU/MAU·classic 리텐션 {#habit-dashboard}&quot;\\">&ZeroWidthSpace;</a></h3>\\n<ul>\\n<li>관리자 분석 화면 맨 위에 <strong>습관 지표</strong>: 북극성 L7 습관층(최근 7일 중 3일 이상 쓴 사람 비율)과 7일 중 쓴 날 분포, 쓴 사람 DAU·WAU·MAU·DAU/MAU(연 사람은 보조) → <a href=\\"/grato-docs/operations/metrics#activity-dashboard\\">습관 지표 화면</a></li>\\n<li>가입 주별 다시 오는 비율을 classic·rolling 함께(쓴 사람 / 연 사람 기준 고르기), 8주 추이</li>\\n<li>수익화 관문 두 칸: M6 ≥ 25%, 쓴 사람 DAU/MAU ≥ 20% (통과·미달 표시)</li>\\n<li>매일 밤 집계 문서만 읽음(열 때 약 170개). GRATO-32 함수와 함께 배포 → <a href=\\"/grato-docs/operations/deploy#release-activity-metrics\\">배포</a></li>\\n</ul>\\n"},{"id":"GRATO-84","html":"<h3 id=\\"open-circle-member-profiles\\" tabindex=\\"-1\\">모두의 감사방: 이 방에서만 만난 사람의 실제 프로필은 보이지 않음 <a class=\\"header-anchor\\" href=\\"#open-circle-member-profiles\\" aria-label=\\"Permalink to &quot;모두의 감사방: 이 방에서만 만난 사람의 실제 프로필은 보이지 않음 {#open-circle-member-profiles}&quot;\\">&ZeroWidthSpace;</a></h3>\\n<ul>\\n<li>모두의 감사방 멤버는 다른 사람의 공개 프로필을 본인·다른 Circle을 함께 쓰는 사람·운영자만 읽습니다. 멤버가 아닌 사람은 그대로입니다. → <a href=\\"/grato-docs/architecture/security-rules#open-circle-profiles\\">보안 규칙</a></li>\\n<li>읽을 수 없는 프로필은 멤버 목록에서 &quot;사용자&quot;, 차단 목록에서 &quot;알 수 없는 사용자&quot;로 보입니다.</li>\\n<li>이 방이 생기기 전 앱(iOS 1.0.0)에서는 이 방에 글·댓글을 남길 수 없습니다. 앱 업데이트 안내 → <a href=\\"/grato-docs/features/circles#open-circle\\">모두의 감사방</a></li>\\n<li>배포: 규칙(<code>firestore:rules</code>) → Hosting. 모두의 감사방을 켜기 전에.</li>\\n</ul>\\n"},{"id":"GRATO-89","html":"<h3 id=\\"short-links-server\\" tabindex=\\"-1\\">짧은 공유 링크 서버: /g /c /b /i <a class=\\"header-anchor\\" href=\\"#short-links-server\\" aria-label=\\"Permalink to &quot;짧은 공유 링크 서버: /g /c /b /i {#short-links-server}&quot;\\">&ZeroWidthSpace;</a></h3>\\n<ul>\\n<li>서버가 짧은 공유 링크를 엽니다: 감사 글 <code>grato.today/g/{코드}</code>, 캘린더 월 <code>/c/{코드}</code>, 배지 <code>/b/{코드}</code>, 초대 <code>/i/{초대 코드}</code>. 링크와 페이지 데이터에 uid가 없고, 미리보기는 긴 링크와 같습니다. 공개를 끄면 짧은 링크도 바로 &quot;비공개&quot;입니다. 긴 링크는 그대로 열립니다 → <a href=\\"/grato-docs/features/gratitudes#short-links\\">짧은 링크</a></li>\\n<li>새 callable <code>createShortLink</code>(본인 것이고 공개된 것만, 같은 대상은 같은 코드, 하루 100개), 서버 전용 컬렉션 <code>shortLinks</code>·<code>shortLinkTargets</code>·<code>shortLinkQuota</code>(TTL). 글·계정을 지우면 짧은 링크도 지웁니다</li>\\n<li>배포: functions·firestore(TTL) → hosting(rewrites). 공유 버튼이 짧은 링크를 쓰는 것은 GRATO-90 → <a href=\\"/grato-docs/operations/deploy#release-short-links\\">배포</a></li>\\n</ul>\\n"},{"id":"GRATO-90","html":"<h3 id=\\"short-links-client\\" tabindex=\\"-1\\">공유 메시지에 짧은 링크, 초대는 /i/ <a class=\\"header-anchor\\" href=\\"#short-links-client\\" aria-label=\\"Permalink to &quot;공유 메시지에 짧은 링크, 초대는 /i/ {#short-links-client}&quot;\\">&ZeroWidthSpace;</a></h3>\\n<ul>\\n<li>감사 글·캘린더 월·배지를 공유하면 메시지에 짧은 링크(<code>grato.today/g/…</code>, <code>/c/…</code>, <code>/b/…</code>)가 들어갑니다. 짧은 링크를 못 받으면 지금처럼 긴 링크로 공유합니다(공유가 막히지 않음). 앱은 최대 1.5초 기다리고, 웹은 미리 받아 둔 링크만 씁니다(웹에서 처음 공개하며 공유하면 긴 링크) → <a href=\\"/grato-docs/features/gratitudes#short-links\\">짧은 링크</a></li>\\n<li>초대 메시지의 링크가 <code>grato.today/i/{코드}</code>로 짧아집니다. 전에 보낸 <code>/invite/…</code> 링크도 그대로 열립니다</li>\\n<li>웹 화면 <code>/i/:code</code>, <code>/g/:code</code>, <code>/c/:code</code>, <code>/b/:code</code>, <code>/go/:name</code>(대비용). Android 앱 1.0.1 (7)은 <code>/i/</code> 링크를 앱에서 엽니다. iOS는 1.0.1 (7)이 퍼진 뒤 AASA에 <code>/i/*</code>를 더합니다 → <a href=\\"/grato-docs/mobile/#deep-links\\">링크로 앱 열기</a></li>\\n<li>배포: GRATO-89 서버 다음에 Hosting, 앱은 1.0.1 (7) → <a href=\\"/grato-docs/operations/deploy#release-short-links-client\\">배포</a></li>\\n<li>앱이 있어도 공유 링크(<code>/share/…</code>, <code>/g/…</code> 등)는 브라우저에서 열려 다른 사람이 공개한 내용이 보입니다(앱 화면에는 서버가 주는 공유 데이터가 없어 비어 보였음). iOS는 AASA에서 <code>/share/*</code>를 빼는 Hosting 배포부터, Android는 1.0.1 (7)부터 → <a href=\\"/grato-docs/mobile/#deep-links\\">링크로 앱 열기</a></li>\\n</ul>\\n"},{"id":"GRATO-91","html":"<h3 id=\\"campaign-links\\" tabindex=\\"-1\\">캠페인 짧은 링크 /go/{이름} <a class=\\"header-anchor\\" href=\\"#campaign-links\\" aria-label=\\"Permalink to &quot;캠페인 짧은 링크 /go/{이름} {#campaign-links}&quot;\\">&ZeroWidthSpace;</a></h3>\\n<ul>\\n<li><code>grato.today/go/{이름}</code>이 302로 사이트 페이지(+UTM)나 App Store 캠페인 링크로 보냅니다. 웹 대상이면 가입 유입 경로가 지금처럼 잡히고, 연 횟수는 <code>campaign_link_open</code>(uid·기기 정보 없음)으로 셉니다 → <a href=\\"/grato-docs/operations/deploy#campaign-links\\">캠페인 링크</a></li>\\n<li>만들기는 스크립트 <code>setupCampaignLink</code>(관리자 화면 없음), 서버 전용 컬렉션 <code>campaignLinks</code></li>\\n<li>배포: <code>shareRenderer</code> → Hosting(<code>/go/**</code> rewrite)</li>\\n</ul>\\n"},{"id":"GRATO-93","html":"<h3 id=\\"question-facets\\" tabindex=\\"-1\\">오늘의 질문: 요일마다 다른 결 <a class=\\"header-anchor\\" href=\\"#question-facets\\" aria-label=\\"Permalink to &quot;오늘의 질문: 요일마다 다른 결 {#question-facets}&quot;\\">&ZeroWidthSpace;</a></h3>\\n<ul>\\n<li>시즌 밖(11/14까지, 1/11부터)의 오늘의 질문이 요일마다 정한 결에서 나옵니다: 월 작은 것 · 화 사람 · 수 없었다면 · 목 특정 순간 · 금 고마움 잇기 · 토 섞인 감정 · 일 한 주 돌아보기. 같은 결의 질문은 주마다 하나씩 돌아 목록을 다 돌기 전에 다시 나오지 않습니다. 위젯도 같은 질문입니다. 시즌(11/15–1/10)에는 지금처럼 시즌 질문이 먼저입니다. → <a href=\\"/grato-docs/features/guided-writing#facets\\">요일별 결</a></li>\\n<li>기본 첫 질문이 30개에서 45개가 됐습니다(없었다면·고마움 잇기·섞인 감정·한 주 돌아보기 질문 15개). 물건 쪽 질문 2개(음식, 선물)를 사람·경험 쪽으로 고쳤습니다. &quot;다른 질문&quot;과 한 줄 저장은 그대로입니다.</li>\\n<li>운영자가 사용자 질문을 선정할 때 결을 고릅니다. 고르면 그 요일의 순환에, 비우면 &quot;다른 질문&quot;에만 나옵니다. 질문 하나가 선정돼도 다른 결의 날은 바뀌지 않습니다. → <a href=\\"/grato-docs/features/questions#review\\">운영자 검토</a></li>\\n<li>배포: 함수(<code>reviewQuestion</code>) → <code>seedQuestions</code>(facet·order·새 질문 15개) → Hosting. 앱은 1.0.1 (7)부터. 카드뉴스는 질문 수가 45개로 늘어 다음 주부터 순서가 바뀝니다. → <a href=\\"/grato-docs/operations/deploy#seed-questions\\">배포: 기본 질문 시드</a></li>\\n</ul>\\n"},{"id":"GRATO-101","html":"<h3 id=\\"theme-template\\" tabindex=\\"-1\\">이미지 테마 템플릿: 작가 그림으로 새 테마 <a class=\\"header-anchor\\" href=\\"#theme-template\\" aria-label=\\"Permalink to &quot;이미지 테마 템플릿: 작가 그림으로 새 테마 {#theme-template}&quot;\\">&ZeroWidthSpace;</a></h3>\\n<ul>\\n<li>작가가 색·칸 아이콘·그림 층(PNG)만 넣으면 코드 수정 없이 새 이미지 테마가 되는 템플릿과 등록 스크립트(<code>resources/theme-template/</code>, <code>add-theme.mjs</code>). → <a href=\\"/grato-docs/operations/theme-template\\">이미지 테마 템플릿</a></li>\\n<li>이미지(캘린더·감사 글·배지·초대장·올해 돌아보기)가 테마의 그림 층을 그립니다. 지금 있는 테마의 모습은 그대로입니다.</li>\\n</ul>\\n"},{"id":"GRATO-102","html":"<h3 id=\\"cell-icons\\" tabindex=\\"-1\\">캘린더 칸 아이콘: 시즌 테마는 기록한 날을 아이콘으로 <a class=\\"header-anchor\\" href=\\"#cell-icons\\" aria-label=\\"Permalink to &quot;캘린더 칸 아이콘: 시즌 테마는 기록한 날을 아이콘으로 {#cell-icons}&quot;\\">&ZeroWidthSpace;</a></h3>\\n<ul>\\n<li>겨울 테마는 별, 신년 테마는 해 아이콘으로 기록한 날을 채웁니다(캘린더 이미지와 마이페이지 캘린더). 한 달 내내 같은 아이콘 하나이고, 기본 테마는 지금처럼 색 동그라미입니다. → <a href=\\"/grato-docs/features/stats-badges#cell-icons\\">캘린더 칸 아이콘</a></li>\\n<li>마이페이지 캘린더는 이미지 시트에서 마지막으로 고른 테마(없으면 가장 최근에 받은 테마)를 따릅니다. 테마가 없으면 바뀌지 않습니다.</li>\\n<li>예전 앱(1.0.1 (6) 이하)은 같은 테마도 색 동그라미로 그립니다.</li>\\n</ul>\\n"},{"id":"GRATO-104","html":"<h3 id=\\"server-seasons\\" tabindex=\\"-1\\">관리자에서 시즌 만들기·게시 (앱 업데이트 없이) <a class=\\"header-anchor\\" href=\\"#server-seasons\\" aria-label=\\"Permalink to &quot;관리자에서 시즌 만들기·게시 (앱 업데이트 없이) {#server-seasons}&quot;\\">&ZeroWidthSpace;</a></h3>\\n<ul>\\n<li>관리자 › <strong>시즌</strong> 탭: 시즌(이름·첫날·질문·날짜 순서·매일 알림 문구)을 만들고, 날짜별 미리보기로 확인하고, 게시·끝내기. 앱 안 시즌을 불러와 고칠 수 있습니다. 쓰기는 운영자 callable <code>manageSeason</code>만(감사 기록). → <a href=\\"/grato-docs/features/guided-writing#server-seasons\\">서버 시즌</a>, <a href=\\"/grato-docs/operations/deploy#server-seasons\\">운영</a></li>\\n<li>앱(1.0.1 (7)부터)과 웹은 게시된 시즌을 세션에 한 번 뒤에서 읽어 그날의 질문·이어지는 질문·위젯·매일 알림 문구에 씁니다. 같은 시즌 키는 서버가 이기고, 끝낸 시즌은 꺼집니다. 못 읽으면 앱 안 시즌 그대로. → <a href=\\"/grato-docs/decisions#adr-41\\">ADR-41</a></li>\\n<li>웹 매일 알림(<code>sendDailyReminder</code>)도 서버 시즌 문구를 씁니다.</li>\\n<li>예전 앱(1.0.1 (6) 이하)은 서버 시즌의 질문을 &quot;다른 질문&quot;에서 만납니다.</li>\\n</ul>\\n"},{"id":"GRATO-105","html":"<h3 id=\\"button-colors-logo-amber\\" tabindex=\\"-1\\">주 버튼을 로고 앰버 색으로, 앰버 글자·포커스·위험 버튼 대비 AA <a class=\\"header-anchor\\" href=\\"#button-colors-logo-amber\\" aria-label=\\"Permalink to &quot;주 버튼을 로고 앰버 색으로, 앰버 글자·포커스·위험 버튼 대비 AA {#button-colors-logo-amber}&quot;\\">&ZeroWidthSpace;</a></h3>\\n<ul>\\n<li>주 버튼·쓰기 버튼·선택한 탭과 칩이 다시 로고와 같은 밝은 앰버(<code>#F59E0B</code>)가 됩니다. 글자는 흰색 대신 짙은 갈색이라 더 잘 읽힙니다(6.97:1). 남아 있던 흰 글자 앰버 버튼 2곳(앱 설치 카드, 알림 설정의 앱 링크)도 같이 바뀝니다.</li>\\n<li>스위치·라디오·체크·입력 칸 포커스·키보드 포커스 링은 한 단계 짙은 앰버(<code>#D97706</code>)로 흰 바탕에서 3:1을 넘깁니다. 앰버 강조 글자·링크(로그인 &quot;회원가입&quot; 등)는 <code>#B45309</code>로 4.5:1을 넘깁니다.</li>\\n<li>삭제·계정 삭제 같은 위험 버튼은 <code>red-600</code>(4.83:1).</li>\\n<li>웹 Hosting 배포와 다음 앱 빌드에 들어갑니다. 서버·규칙 변경 없음 → <a href=\\"/grato-docs/architecture/client#visual-style\\">화면 스타일</a>, <a href=\\"/grato-docs/decisions#adr-46\\">ADR-46</a></li>\\n</ul>\\n"},{"id":"GRATO-109","html":"<h3 id=\\"open-circle-first-response\\" tabindex=\\"-1\\">모두의 감사방 첫 반응 기록 (운영 지표) <a class=\\"header-anchor\\" href=\\"#open-circle-first-response\\" aria-label=\\"Permalink to &quot;모두의 감사방 첫 반응 기록 (운영 지표) {#open-circle-first-response}&quot;\\">&ZeroWidthSpace;</a></h3>\\n<ul>\\n<li>서버만: 모두의 감사방 글에 만든 지 72시간 안에 처음 달린 멤버의 공감·댓글 시각과 종류를 글에 한 번 남깁니다(운영 계정의 반응은 빼고, 누가 반응했는지는 남기지 않음). 관리자 지표의 &quot;24시간 첫 반응&quot;용. 화면 변화 없음 → <a href=\\"/grato-docs/operations/metrics#open-circle-first-response\\">첫 반응 기록</a></li>\\n<li>관리자 분석 화면에 <strong>모두의 감사방</strong> 칸: 기간을 골라 참여·이 방에 나눈 글·오늘의 주제 참여율·답의 24시간 첫 반응·다음 날 재기록·신고와 처리를 봅니다(운영 계정 제외, 1–2명인 칸은 &quot;3명 미만&quot;) → <a href=\\"/grato-docs/operations/metrics#open-circle\\">모두의 감사방 지표</a></li>\\n</ul>\\n"},{"id":"GRATO-110","html":"<h3 id=\\"contrast-followups\\" tabindex=\\"-1\\">글자 대비: 위젯과 설정 화면 <a class=\\"header-anchor\\" href=\\"#contrast-followups\\" aria-label=\\"Permalink to &quot;글자 대비: 위젯과 설정 화면 {#contrast-followups}&quot;\\">&ZeroWidthSpace;</a></h3>\\n<ul>\\n<li>홈 화면 위젯(iOS·Android): &quot;오늘 기록 완료 ✓&quot;와 &quot;오늘의 질문&quot; 라벨을 짙은 앰버(<code>#B45309</code>)로, 요일 글자를 <code>#6B7280</code>으로 — 밝은 바탕에서 읽기 쉽게(4.5:1 이상). 새싹 마크·점 색은 그대로. 다음 앱 빌드(1.0.1 (7))부터</li>\\n<li>설정·Circle 설정 화면의 빨간 상태·오류 글자, 나가기·삭제 버튼 글자, 초록 &quot;켜져 있어요&quot; 글자를 한 단계 짙게</li>\\n<li>캘린더 이미지의 &quot;n일&quot;은 이미 테마 색(4.5:1 이상)이라 바뀌지 않음 → <a href=\\"/grato-docs/architecture/client#visual-style\\">화면 스타일</a></li>\\n</ul>\\n"},{"id":"GRATO-111","html":"<h3 id=\\"harvest-theme\\" tabindex=\\"-1\\">가을 이미지 테마 (감사의 계절 보상) <a class=\\"header-anchor\\" href=\\"#harvest-theme\\" aria-label=\\"Permalink to &quot;가을 이미지 테마 (감사의 계절 보상) {#harvest-theme}&quot;\\">&ZeroWidthSpace;</a></h3>\\n<ul>\\n<li>새 이미지 테마 <strong>가을</strong>: 귀리빛 바탕에 감 가지·잎·벼 이삭 그림, 캘린더의 기록한 날은 감 아이콘. 감사의 계절(11/15–11/30) 시즌 배지를 받은 사람만 이미지 시트에서 고를 수 있어요. 웹은 바로, 앱은 1.0.1 (7)부터 → <a href=\\"/grato-docs/features/stats-badges#themes\\">이미지 테마</a></li>\\n<li>작가 템플릿으로 만든 첫 테마입니다(앱 코드 수정 없이 등록) → <a href=\\"/grato-docs/operations/theme-template\\">이미지 테마 템플릿</a></li>\\n</ul>\\n"},{"id":"GRATO-112","html":"<h3 id=\\"my-theme\\" tabindex=\\"-1\\">내 테마: 마이페이지에서 고르고 계정에 저장 <a class=\\"header-anchor\\" href=\\"#my-theme\\" aria-label=\\"Permalink to &quot;내 테마: 마이페이지에서 고르고 계정에 저장 {#my-theme}&quot;\\">&ZeroWidthSpace;</a></h3>\\n<ul>\\n<li>마이페이지에 <strong>&quot;내 테마&quot;</strong> 카드가 생겼습니다. 받은 테마를 캘린더 칸 미리보기로 보고 고를 수 있고, 기본 테마는 늘 고를 수 있습니다. 아직 받지 못한 테마는 잠금으로, 어느 배지를 받으면 열리는지(기간 포함) 함께 보입니다. → <a href=\\"/grato-docs/features/stats-badges#my-theme\\">내 테마</a>, <a href=\\"/grato-docs/operations/deploy#release-my-theme\\">배포</a></li>\\n<li>고른 테마는 이제 계정에 저장돼 웹·앱·다른 기기에서 같습니다(<code>users.imageTheme</code>, 규칙은 받은 테마만 허용). 이미지 시트의 테마 칩도 같은 값을 바꿉니다. 이 기기에서 전에 고른 테마는 처음 한 번 계정으로 옮겨집니다.</li>\\n<li>1.0.1 (6) 이하 앱은 지금처럼 기기에 저장한 테마를 씁니다.</li>\\n</ul>\\n"},{"id":"GRATO-112-theme-everywhere","html":"<h3 id=\\"grato-112-theme-everywhere\\" tabindex=\\"-1\\">고른 테마가 캘린더와 위젯에도 <a class=\\"header-anchor\\" href=\\"#grato-112-theme-everywhere\\" aria-label=\\"Permalink to &quot;고른 테마가 캘린더와 위젯에도 {#grato-112-theme-everywhere}&quot;\\">&ZeroWidthSpace;</a></h3>\\n<ul>\\n<li>&quot;내 테마&quot;에서 고른 테마가 공유 이미지뿐 아니라 <strong>마이페이지 캘린더</strong>(기록한 날 동그라미, 오늘 테두리, 숫자 색)와 <strong>홈 화면 위젯</strong>(iOS·Android: 배경, 카드, 글자, 이번 주 점)에도 쓰입니다. 기본 테마는 지금 모습 그대로입니다.</li>\\n<li>위젯 색은 테마를 읽는 앱 업데이트(1.0.1 (7))부터 바뀝니다.</li>\\n</ul>\\n"},{"id":"QA-1019","html":"<h3 id=\\"qa-1019-stg-fixes\\" tabindex=\\"-1\\">stg 점검 뒤 고친 것: 추천 바로 반영, 시즌 질문 순서 <a class=\\"header-anchor\\" href=\\"#qa-1019-stg-fixes\\" aria-label=\\"Permalink to &quot;stg 점검 뒤 고친 것: 추천 바로 반영, 시즌 질문 순서 {#qa-1019-stg-fixes}&quot;\\">&ZeroWidthSpace;</a></h3>\\n<ul>\\n<li>&quot;추천 많은 질문&quot;: 방금 추천한 질문이 같은 세션에서 바로 순서에 반영됩니다(다음에 앱을 열 때 서버 숫자로 맞춰짐).</li>\\n<li>관리자 › 시즌: 저장한 시즌을 다시 열면 질문이 날짜 순서대로 보입니다(저장된 값은 그대로).</li>\\n<li>stg 공유 페이지(<code>/share</code> <code>/g</code> <code>/c</code> <code>/b</code> <code>/i</code>)가 stg Hosting의 템플릿을 씁니다(운영 영향 없음).</li>\\n</ul>\\n"},{"id":"QA-1020-badges","html":"<h3 id=\\"qa-1020-badges\\" tabindex=\\"-1\\">배지가 지급되지 않던 문제 <a class=\\"header-anchor\\" href=\\"#qa-1020-badges\\" aria-label=\\"Permalink to &quot;배지가 지급되지 않던 문제 {#qa-1020-badges}&quot;\\">&ZeroWidthSpace;</a></h3>\\n<ul>\\n<li>새 질문 배지(질문으로 쓰인 감사, 추천받은 질문)를 세는 집계에 필요한 인덱스가 빠져 배지 검사 전체가 실패하던 문제를 고쳤습니다(stg에서 발견, 운영 배포 전).</li>\\n<li>배지 검사의 숫자 하나를 세지 못해도 그 배지만 다음으로 미루고 나머지 배지는 그대로 지급합니다.</li>\\n</ul>\\n"},{"id":"QA-1020-cells","html":"<h3 id=\\"qa-1020-cells\\" tabindex=\\"-1\\">캘린더 기록한 날은 다시 동그라미로 <a class=\\"header-anchor\\" href=\\"#qa-1020-cells\\" aria-label=\\"Permalink to &quot;캘린더 기록한 날은 다시 동그라미로 {#qa-1020-cells}&quot;\\">&ZeroWidthSpace;</a></h3>\\n<ul>\\n<li>시즌 테마의 캘린더 칸 아이콘(열매·별·해·감)을 잠시 끄고, 모든 테마가 기록한 날을 테마 색 동그라미로 그립니다(마이페이지 캘린더, 캘린더 이미지, &quot;내 테마&quot; 미리보기). 새 그림이 준비되면 다시 켭니다.</li>\\n</ul>\\n"},{"id":"RELEASE-1-0-1-7","html":"<h3 id=\\"release-1-0-1-7\\" tabindex=\\"-1\\">앱 1.0.1 (7): 1.0.2 예정분을 합쳐 출시 <a class=\\"header-anchor\\" href=\\"#release-1-0-1-7\\" aria-label=\\"Permalink to &quot;앱 1.0.1 (7): 1.0.2 예정분을 합쳐 출시 {#release-1-0-1-7}&quot;\\">&ZeroWidthSpace;</a></h3>\\n<ul>\\n<li>1.0.2에 넣으려던 기능(짧은 공유 링크, 질문 추천과 요일별 질문, 서버 시즌, 내 테마와 테마 반영, 버튼 색 등)을 1.0.1 (7)에 함께 담아 iOS·Android에 냅니다. 문서의 &quot;앱 1.0.2부터&quot;는 &quot;1.0.1 (7)부터&quot;로 바꿨습니다. → <a href=\\"/grato-docs/operations/deploy#release-1-0-1-7\\">배포</a></li>\\n</ul>\\n"}]`),n={key:0},u=["innerHTML"],f=JSON.parse('{"title":"변경 이력","description":"","frontmatter":{},"headers":[],"relativePath":"changelog.md","filePath":"changelog.md","lastUpdated":1792284239000}'),h={name:"changelog.md"},m=Object.assign(h,{setup(q){return(g,e)=>(o(),a("div",null,[e[0]||(e[0]=r("",4)),t(l).length?s("",!0):(o(),a("p",n,"없음")),(o(!0),a(c,null,d(t(l),i=>(o(),a("div",{key:i.id,class:"unreleased-entry",innerHTML:i.html},null,8,u))),128)),e[1]||(e[1]=r("",172))]))}});export{f as __pageData,m as default};
